class InvalidSchoolScoreException extends Exception { InvalidSchoolScoreException(String message){super(message);} }
public class SchoolExceptionHandlingDemo { static void validateScore(int score)throws InvalidSchoolScoreException{if(score<0||score>100)throw new InvalidSchoolScoreException("Score must be between 0 and 100");} public static void main(String[] args){int[] scores={85,120,42};for(int score:scores){try{validateScore(score);System.out.println("Accepted score: "+score);}catch(InvalidSchoolScoreException ex){System.out.println("Rejected: "+ex.getMessage());}finally{System.out.println("Validation finished for "+score);}}} }
